using UnityEngine;using UnityEngine.UI; namespace Mojinloop.Combat { public sealed class CoinDropEffect:MonoBehaviour { float life;Text label;public void Play(int coins,Vector3 world,Canvas canvas){label=GetComponent<Text>();label.text=$"+{coins} coin";transform.SetParent(canvas.transform,false);transform.position=Camera.main.WorldToScreenPoint(world);life=.8f;}void Update(){life-=Time.unscaledDeltaTime;transform.position+=Vector3.up*22f*Time.unscaledDeltaTime;if(label!=null)label.color=new Color(1,.75f,.1f,Mathf.Clamp01(life*2));if(life<=0)Destroy(gameObject);} } }
